export const classes=['positive','negative','neutral'];
export const rules={'Geopolitical':['war','sanctions','conflict','geopolitical','invasion'],'Macroeconomic':['inflation','interest rate','recession','central bank','unemployment'],'Credit Event':['default','bankruptcy','liquidity','downgrade','debt'],'Merger/Acquisition':['merger','acquisition','takeover'],'Product Launch':['product','launch','recall']};
export const shocks={'Geopolitical':[-.10,.02,.015],'Macroeconomic':[-.08,.02,.005],'Credit Event':[-.12,0,.025],'Merger/Acquisition':[-.04,0,.004],'Product Launch':[-.03,0,.002],'Other':[-.02,0,.001]};
const tokens=t=>t.toLowerCase().replace(/https?:\/\/\S+/g,' ').match(/[a-z]+/g)||[];
export const aliases={AAPL:['apple'],MSFT:['microsoft'],NVDA:['nvidia'],AMZN:['amazon'],GOOGL:['alphabet','google'],META:['meta','facebook'],TSLA:['tesla'],JPM:['jpmorgan','j.p. morgan'],V:['visa'],WMT:['walmart']};
export function inferCompany(text){for(const [t,ws]of Object.entries(aliases)){if(new RegExp('\\$'+t+'\\b','i').test(text)||ws.some(w=>new RegExp('\\b'+w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i').test(text)))return t}return 'GLOBAL'}
export function createEngine(model){return row=>{if(typeof row.text!=='string'||!row.text.trim()||row.text.length>20000)throw Error('Text must contain 1 to 20000 characters');const ts=tokens(row.text),features={};for(const t of [...ts,...ts.slice(0,-1).map((t,i)=>t+' '+ts[i+1])])features[t]=(features[t]||0)+1;const weighted=[];let norm=0;for(const [k,n]of Object.entries(features)){const i=model.vocabulary[k];if(i!==undefined){const v=(1+Math.log(n))*model.idf[i];weighted.push([i,v]);norm+=v*v}}norm=Math.sqrt(norm)||1;const scores=model.coefficients.map((coef,c)=>model.intercepts[c]+weighted.reduce((s,[i,v])=>s+coef[i]*v/norm,0));const max=Math.max(...scores),exps=scores.map(v=>Math.exp(v-max)),z=exps.reduce((s,v)=>s+v,0),probabilities={};model.classes.forEach((c,i)=>probabilities[c]=exps[i]/z);const low=row.text.toLowerCase(),hits={};for(const [k,ws]of Object.entries(rules))hits[k]=ws.filter(w=>new RegExp('\\b'+w+'\\b').test(low));let event=Object.keys(hits).sort((a,b)=>hits[b].length-hits[a].length)[0];if(!hits[event].length)event='Other';const severity=['war','default','bankruptcy','crisis','sanctions','recession','fraud'].filter(w=>new RegExp('\\b'+w+'\\b').test(low));return {...row,company:row.company||inferCompany(row.text),sentiment_score:+(probabilities.positive-probabilities.negative).toFixed(4),sentiment_label:classes.reduce((a,b)=>probabilities[a]>=probabilities[b]?a:b),probabilities,event_classification:event,impact_score:Math.min(10,1+2*severity.length+(hits[event]||[]).length),evidence:{event_keywords:hits[event]||[],severity_keywords:severity},model:model.model,impact_method:'keyword heuristic',confidence_calibrated:false,low_confidence:Math.max(...Object.values(probabilities))<.55,matched_features:weighted.length}}}
export function stress(s,portfolio,threshold=7,multiplier=1){if(multiplier<0||multiplier>3)throw Error('Multiplier must be 0 to 3');const triggered=s.impact_score>threshold;const [eq,rate,spread]=(shocks[s.event_classification]||shocks.Other).map(v=>triggered?v*multiplier:0);const assets=portfolio.map(a=>{const change=a.value*((a.equity_beta||0)*eq-(a.duration||0)*rate-(a.spread_duration||0)*spread)+(a.rate_sensitivity||0)*rate;return {...a,before:a.value,after:a.value+change,change}});const before=assets.reduce((s,a)=>s+a.before,0),after=assets.reduce((s,a)=>s+a.after,0);return {triggered,assets,before,after,loss:before-after,loss_pct:before?(before-after)/before*100:0,shock:{equity:eq,rates:rate,spread}}}
export function rebalance(signals){const ts=['AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','JPM','V','WMT'],latest={};for(const s of signals)latest[s.company]=s;const raw=ts.map(t=>1+.5*(latest[t]?.sentiment_score||0)),total=raw.reduce((a,b)=>a+b,0);return ts.map((t,i)=>({ticker:t,base_weight:.1,weight:raw[i]/total,sentiment:latest[t]?.sentiment_score||0}))}
